/// Sentinel matching `AppConstants.unconfiguredFirebaseApiKey`, which
/// `main.dart` checks to detect that Firebase has not been set up yet.
///
/// It is written as a literal rather than a shared constant because
/// `flutterfire configure` replaces this entire file — nothing else may import
/// a symbol defined here.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError(
        'This project targets Android. Run `flutterfire configure` to add web.',
      );
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      default:
        throw UnsupportedError(
          'CatchEvent is configured for Android. Run `flutterfire configure` '
          'to add ${defaultTargetPlatform.name}.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyDyMD7bAOeNpXWUlu3nn8v6S3xLkx6V1F8',
    appId: '1:697438257500:android:c07194fb140ac011f24199',
